INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(42611, 'Genesis 27:27', 'Genesis', 27, 27, 'نو یعقوب ورنژدې شو او هغه یې ښکل کړ. نو کله چې اسحاق د هغه کالي بوی کړل، نو ده ته یې برکت ورکړ او ویې ویل: «زما د زوی خوږ بوی د هغې صحرا د بوی په شان دی چې څښتن هغې ته برکت ورکړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_27.mp3', '', 1761754199, 1761754199),
(42612, 'Genesis 27:28', 'Genesis', 27, 28, 'خدای دې تاته د اسمان نه پرخه درکړي او ستا ځمکه دې حاصلخېزه کړي! او پرېمانه غلې دانې او شراب دې درکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_28.mp3', '', 1761754199, 1761754199),
(42613, 'Genesis 27:29', 'Genesis', 27, 29, 'قومونه دې ستا غلامان شي او تاته دې د درناوي په خاطر سر ټیټوي او ته دې په خپلو خپلوانو باندې حکم چلوې او ستا د مور اولاده دې تاته سر ټیټوي. څوک چې په تا باندې لعنت ووایي، په هغه باندې دې لعنت وي او څوک چې برکت درکوي، په هغه دې برکت وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_29.mp3', '', 1761754199, 1761754199),
(42614, 'Genesis 27:30', 'Genesis', 27, 30, 'سمدلاسه وروسته له دې چې هغه له برکت ورکولو څخه وزګار شو او یعقوب لاړ، د یعقوب ورور عیسو د ښکار څخه راغی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_30.mp3', '', 1761754199, 1761754199),
(42615, 'Genesis 27:31', 'Genesis', 27, 31, 'هغه هم خوندور خوراک تیار کړ او خپل پلار ته یې راوړ او ویې ویل: «ای پلاره، راپاڅېږه او زما د ښکار لږه غوښه وخوره، ترڅو ماته برکت راکړې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_31.mp3', '', 1761754199, 1761754199),
(42616, 'Genesis 27:32', 'Genesis', 27, 32, 'اسحاق د هغه څخه پوښتنه وکړه: «ته څوک یې؟» هغه ځواب ورکړ: «زه ستا زوی یم، ستا مشر زوی عیسو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_32.mp3', '', 1761754199, 1761754199),
(42617, 'Genesis 27:33', 'Genesis', 27, 33, 'اسحاق سخت ولړزېده او ویې ویل: «نو بیا هغه څوک ؤ چې ښکار یې کړی ؤ او غوښه یې ماته راوړې وه؟ او همدا‌اوس ستا د راتللو څخه مخکې مې هغه وخوړله او هغه ته مې برکت ورکړ او هغه بېرته نه اخیستل کیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_33.mp3', '', 1761754199, 1761754199),
(42618, 'Genesis 27:34', 'Genesis', 27, 34, 'کله چې عیسو د خپل پلار خبرې واورېدلې، هغه په لوړ او سخت اواز سره چیغې ووهلې او خپل پلار ته یې وویل: «ای زما پلاره، ماته هم برکت راکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_34.mp3', '', 1761754199, 1761754199),
(42619, 'Genesis 27:35', 'Genesis', 27, 35, 'اسحاق ځواب ورکړ: «ستا ورور دلته راغی، زه یې وغولولم او ستا برکت یې واخیست.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_35.mp3', '', 1761754199, 1761754199),
(42620, 'Genesis 27:36', 'Genesis', 27, 36, 'عیسو وویل: «ایا په هغه باندې یې د یعقوب نوم په حقه نه دی ایښی؟ ځکه چې هغه زه دوه وارې وغولولم. لومړی یې زما څخه د مشرتوب حق واخیست او اوس یې زما برکت واخیست.» نو هغه پوښتنه وکړه: «ایا ماته دې کوم برکت نه دی ساتلی؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_36.mp3', '', 1761754199, 1761754199),
(42621, 'Genesis 27:37', 'Genesis', 27, 37, 'اسحاق عیسو ته په ځواب کې وویل: «هغه مې په تا باندې بادار کړی دی او د هغه ټول خپلوان مې د هغه غلامان کړل او هغه ته مې غلې دانې او شراب ورکړي دي. نو ای زویه! اوس زه ستا دپاره څه وکړم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_37.mp3', '', 1761754199, 1761754199),
(42622, 'Genesis 27:38', 'Genesis', 27, 38, 'عیسو بیا خپل پلار ته وویل: «ای زما پلاره، ایا ستا سره یوازې یو برکت ؤ؟ ماته هم برکت راکړه!» بیا عیسو په لوړ اواز سره وژړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_38.mp3', '', 1761754199, 1761754199),
(42623, 'Genesis 27:39', 'Genesis', 27, 39, 'اسحاق هغه ته وویل: پرخه به نه وي له اسمانه ستا دپاره نه به ځمکه حاصلخېزه وي د ستا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_39.mp3', '', 1761754199, 1761754199),
(42624, 'Genesis 27:40', 'Genesis', 27, 40, 'ژوند به کړې په خپله توره یې غلام به د خپل ورور خو چې ته کله یاغي شې کړې به مات د هغه جغ له خپلې غاړې څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_40.mp3', '', 1761754199, 1761754199),
(42625, 'Genesis 27:41', 'Genesis', 27, 41, 'عیسو د یعقوب سره د هغه برکت له امله چې پلار یې یعقوب ته ورکړی ؤ، کینه پیدا کړه. هغه د خپل ځان سره وویل: «زما پلار مرګ ته نژدې دی او هغه به مړ شي، بیا به خپل ورور یعقوب ووژنم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_41.mp3', '', 1761754199, 1761754199),
(42626, 'Genesis 27:42', 'Genesis', 27, 42, 'کله چې ربکا د خپل مشر زوی عیسو د پلان څخه خبره شوه، هغې خپل کشر زوی یعقوب راوغوښت او ورته ویې ویل: «غوږ ونیسه، ستا ورور عیسو تاته دسیسه جوړوي چې ستا څخه د هغو کارونو بدل واخلي چې تا کړي دي او تا ووژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_42.mp3', '', 1761754199, 1761754199),
(42627, 'Genesis 27:43', 'Genesis', 27, 43, 'نو اوس ای زما زویه، هغه کار وکړه چې زه یې درته وایم. سمدلاسه زما ورور لابان ته چې په حران کې دی، وتښته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_43.mp3', '', 1761754199, 1761754199),
(42628, 'Genesis 27:44', 'Genesis', 27, 44, 'د هغه سره د لږ وخت دپاره پاتې شه، ترڅو ستا د ورور قهر سوړ شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_44.mp3', '', 1761754199, 1761754199),
(42629, 'Genesis 27:45', 'Genesis', 27, 45, 'او هغه څه چې تا ورسره کړي دي، هغه هېر کړي. نو بیا به خبر درولېږم چې له هغه ځای څخه بېرته راشې. تاسو دواړه ولې په یوه ورځ کې له لاسه ورکړم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_45.mp3', '', 1761754199, 1761754199),
(42630, 'Genesis 27:46', 'Genesis', 27, 46, 'ربکا اسحاق ته وویل: «د دې حیتي ښځو له لاسه د خپل ژوند څخه بېزاره شوې یم. که چېرې یعقوب د دې حیتي ښځو څخه د کوې حیتي انجلۍ سره واده وکړي، نو د دې ژوند څخه به ماته مرګ ښه وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis27_verse_46.mp3', '', 1761754199, 1761754199),
(42631, 'Deuteronomy 32:1', 'Deuteronomy', 32, 1, 'ای ځمکې او اسمانه زما خبرې واورئ واورئ په غور سره چې زه څه وایم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_1.mp3', '', 1761754199, 1761754199),
(42632, 'Deuteronomy 32:2', 'Deuteronomy', 32, 2, 'زما تعلیم دې راپرېوځي لکه څاڅکو د باران په شان او په ځمکه دې راپرېوځي لکه د پرخې په شان د باران په شان دې اوري زما خبرې په تنکیو بوټو باندې د نري باران په شان دې ووریږي تنکیو واښو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_2.mp3', '', 1761754199, 1761754199),
(42633, 'Deuteronomy 32:3', 'Deuteronomy', 32, 3, 'زه به کړمه د څښتن د نوم ستاینه او بیانوي دې لویي خپل قوم د هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_3.mp3', '', 1761754199, 1761754199),
(42634, 'Deuteronomy 32:4', 'Deuteronomy', 32, 4, 'څښتن دی د قوي ګټ په شان دي کامل او عادلانه یې ټول کارونه ستاسو خدای دی وفادار او دی رښتینی کړي کارونه هغه سم او باانصافه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_4.mp3', '', 1761754199, 1761754199),
(42635, 'Deuteronomy 32:5', 'Deuteronomy', 32, 5, 'خو تاسو یئ بې وفا او لایق نه یئ د دې چې اوسئ قوم د هغه ستاسو قوم دی ګناهکار او چلباز قوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_5.mp3', '', 1761754199, 1761754199),
(42636, 'Deuteronomy 32:6', 'Deuteronomy', 32, 6, 'ای کم عقلو بې شعوره خلکو ایا دا لار ده چې څښتن سره کوئ دا چلند؟ ستاسو پلار دی او هغه ستاسو خالق دی دی جوړ کړی هغه ستاسو څخه قوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_6.mp3', '', 1761754199, 1761754199),
(42637, 'Deuteronomy 32:7', 'Deuteronomy', 32, 7, 'وکړئ فکر د تېر شوي وخت په هکله هغه وخت چې دی تېر شوی ډېر پخوا وکړئ پوښتنې خپل مور او خپل پلار نه چې څه وشول وکړئ پوښتنې له سپین ږیرو د تېر وخت په هکله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_7.mp3', '', 1761754199, 1761754199),
(42638, 'Deuteronomy 32:8', 'Deuteronomy', 32, 8, 'قومونو ته ورکړې خدای تعالی دي خپلې ځمکې هغه ټاکلي دي ځایونه د قومونو د اوسېدو په خاطر مقررې کړې یې هر قوم ته ساتونکې فرښتې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_8.mp3', '', 1761754199, 1761754199),
(42639, 'Deuteronomy 32:9', 'Deuteronomy', 32, 9, 'خو هغه غوره کړه خپل ځان ته اولاده د یعقوب', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_9.mp3', '', 1761754199, 1761754199),
(42640, 'Deuteronomy 32:10', 'Deuteronomy', 32, 10, 'هغه وموندل په دښته کې هغوی چې سرګردانه ګرځېدل یوه خوشې او یوه داسې صحرا چې زیات بادونه لري ده ساتنه د هغو کړه او په هغوی یې کاوه پام د خپلو سترګو د کسیو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_10.mp3', '', 1761754199, 1761754199),
(42641, 'Deuteronomy 32:11', 'Deuteronomy', 32, 11, 'څښتن دی لکه عقاب چې خپله ځاله ساتي او الوتل کوي په سر باندې د خپلو بچو څښتن تیار دی تل چې خپاره کړي خپل وزرونه او چې راونیسي خپل خلک چې کله لویږي هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_11.mp3', '', 1761754199, 1761754199),
(42642, 'Deuteronomy 32:12', 'Deuteronomy', 32, 12, 'په سفر کې د خپل قوم مشري وکړه خپله څښتن یوازې مرسته نه وه د هغه سره د بل خدای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_12.mp3', '', 1761754199, 1761754199),
(42643, 'Deuteronomy 32:13', 'Deuteronomy', 32, 13, 'څښتن پرېښودل هغوی چې حکومت وکړي د کنعان په لوړو ځمکو باندې او څه چې پټیو کې شنه کېدل دوی به خوړل هغه هغوی ته د ګټونو منځ کې شات ورکړل د زیتون ونې یې شوې شنې په ډبرینه ځمکه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_13.mp3', '', 1761754199, 1761754199),
(42644, 'Deuteronomy 32:14', 'Deuteronomy', 32, 14, 'د هغوی غواګانو او وزو به ورکولې شیدې او مستې هغوی لرل ډېر ښه پسونه او وزې او پادې او هغوی لرل ډېر ښه غنم او شراب', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_14.mp3', '', 1761754199, 1761754199),
(42645, 'Deuteronomy 32:15', 'Deuteronomy', 32, 15, 'د څښتن قوم شتمن شو خو یاغي شو هغوی چاغ وو او خوړله یې ډوډۍ ډېره هغوی واړاوه مخ له خپل خالق خدای نه او هغوی رد کړ خپل قوي ژغورونکی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_15.mp3', '', 1761754199, 1761754199),
(42646, 'Deuteronomy 32:16', 'Deuteronomy', 32, 16, 'په غضب کړلو څښتن بت پرستۍ د هغوی په خپلو بدو عملونو یې راوپاراوه قهر د هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_16.mp3', '', 1761754199, 1761754199),
(42647, 'Deuteronomy 32:17', 'Deuteronomy', 32, 17, 'هغوی وړاندې قربانۍ کړلې پېریانو ته خوشې خدایانو ته چې هېڅکله یې کومک ورسره نه دی کړی هغو نویو خدایانو ته چې هېڅکله یې نیکونو عبادت د هغو نه ؤ کړی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_17.mp3', '', 1761754199, 1761754199),
(42648, 'Deuteronomy 32:18', 'Deuteronomy', 32, 18, 'هغوی هېر کړلو خپل خدای خپل قوي ژغورونکی هغه څوک چا چې ژوند ورکړی دوی ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_18.mp3', '', 1761754199, 1761754199),
(42649, 'Deuteronomy 32:19', 'Deuteronomy', 32, 19, 'چې څښتن کله دا ولیدل په قهر شو او کړل یې رد خپل زامن او خپلې لوڼې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_19.mp3', '', 1761754199, 1761754199),
(42650, 'Deuteronomy 32:20', 'Deuteronomy', 32, 20, 'هغه وویل زه نور نه کومه مرسته د هغوی بیا به وګورم څه کیږي په دې قوم چې دی سرزوری او بې وفا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_20.mp3', '', 1761754199, 1761754199),
(42651, 'Deuteronomy 32:21', 'Deuteronomy', 32, 21, 'راپارولی زما قهر دی هغوی خپلو بتانو په سبب راپارولی یې غیرت دی زما د خپل تش په نامه خدایانو په سبب داسې خدایان دي هغه چې رښتیني نه دي نو زه به کار واخلم د یو تش په نامه قوم څخه چې یې کړم په قهر زه به غیرت د دوی راوپاروم د ناپوهانو په قوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_21.mp3', '', 1761754199, 1761754199),
(42652, 'Deuteronomy 32:22', 'Deuteronomy', 32, 22, 'زما قهر به د اور په شان لمبې ووهي او فصلونه به په ځمکه باندې وسوځوي هغه به ورسیږي د مړو دنیا ته او وسوځوي به بنیادونه د غرو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_22.mp3', '', 1761754199, 1761754199),
(42653, 'Deuteronomy 32:23', 'Deuteronomy', 32, 23, 'نه ختمېدونکي افتونه به نازل کړم په هغوی باندې او خپل ټول غشي به ګوزار کړم په هغوی باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_23.mp3', '', 1761754199, 1761754199),
(42654, 'Deuteronomy 32:24', 'Deuteronomy', 32, 24, 'د لوږې او تبې نه به مړه شي هغوی د هیبتناکو ناروغیو نه به مړه شي هغوی زه به نازل کړمه وحشي حیوانات چې حمله وکړي په هغوی باندې او زه به نازل کړم زهرجن ماران چې هغوی وچیچي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_24.mp3', '', 1761754199, 1761754199),
(42655, 'Deuteronomy 32:25', 'Deuteronomy', 32, 25, 'په سبب د جنګ به مړي وي پراته کوڅو کې او په کورونو به راپرېوځي وحشت مړه به شي پېغلې او ځوانان نه به کوچنیان پاتې شي نه به سپین ږیري', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_25.mp3', '', 1761754199, 1761754199),
(42656, 'Deuteronomy 32:26', 'Deuteronomy', 32, 26, 'ما به بیخي وای تباه کړي هغوی ترڅو چې پاتې نه وای د هېچا یاد کې هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_26.mp3', '', 1761754199, 1761754199),
(42657, 'Deuteronomy 32:27', 'Deuteronomy', 32, 27, 'خو زه د دې نه وېرېدم چې دښمنان به د هغوی وایي چې ورکړې ماتې زما قوم ته هغوی خو دا زه وم چې په خپله مې هغوی ته ماتې ورکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_27.mp3', '', 1761754199, 1761754199),
(42658, 'Deuteronomy 32:28', 'Deuteronomy', 32, 28, 'اسراییل دی یو بې شعوره قوم هېڅ عقل نشته دوی کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_28.mp3', '', 1761754199, 1761754199),
(42659, 'Deuteronomy 32:29', 'Deuteronomy', 32, 29, 'په دې نه پوهیږي دوی چې ولې ماتې وخوړله په دې نه پوهیږي دوی چې څه ورپېښ شول', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_29.mp3', '', 1761754199, 1761754199),
(42660, 'Deuteronomy 32:30', 'Deuteronomy', 32, 30, 'د اسراییلو زرو تنو ولې ماتې وخوړله د دښمن د یوه تن له لاسه او لس زرو وخوړله ماتې له دوه تنو څخه؟ خپل څښتن خدای ؤ اړولی خپل مخ له هغوی هغوی پریښي ؤ خپل قوي خدای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_30.mp3', '', 1761754199, 1761754199),
(42661, 'Deuteronomy 32:31', 'Deuteronomy', 32, 31, 'دښمنان د دوی پوهیږي چې دي کمزوري د هغوی خپل خدایان او قوي نه دي د اسراییلو د خدای په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_31.mp3', '', 1761754199, 1761754199),
(42662, 'Deuteronomy 32:32', 'Deuteronomy', 32, 32, 'د سدوم او عموره په شان فاسد دي دښمنان د هغوی هغوی دي هغو تاکونو په شان چې نیسي زهرجن او ترخه انګور', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_32.mp3', '', 1761754199, 1761754199),
(42663, 'Deuteronomy 32:33', 'Deuteronomy', 32, 33, 'داسې شرابو په شان چې وي جوړ شوي د چمچه مار له زهرو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_33.mp3', '', 1761754199, 1761754199),
(42664, 'Deuteronomy 32:34', 'Deuteronomy', 32, 34, 'دا څښتن ته دي په یاد چې څه وکړل دښمنانو د هغوی هغه کوي انتظار سمې موقعې ته چې ورته ورکړي سزا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_34.mp3', '', 1761754199, 1761754199),
(42665, 'Deuteronomy 32:35', 'Deuteronomy', 32, 35, 'څښتن به واخلي بدله له هغوی او سزا به ورکړي ورته وخت به راشي د هغوی د پرزېدلو رانژدې ده د هغوی د تباهۍ ورځ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_35.mp3', '', 1761754199, 1761754199),
(42666, 'Deuteronomy 32:36', 'Deuteronomy', 32, 36, 'چې کله وویني څښتن چې قوت د ده د قوم دی له منځه تللی نو د هغوی سره به وکړي انصاف کله چې وویني څښتن چې څومره بې وزلي دي هغوی هغه به وکړي زړه سوی په هغو خلکو باندې چې خدمت د هغه کاندي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_36.mp3', '', 1761754199, 1761754199),
(42667, 'Deuteronomy 32:37', 'Deuteronomy', 32, 37, 'بیا به څښتن وکړي پوښتنه داسې له خپله قومه څخه چېرته دي هغه قوي خدایان چې مو باور پرې درلود؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_37.mp3', '', 1761754199, 1761754199),
(42668, 'Deuteronomy 32:38', 'Deuteronomy', 32, 38, 'تاسو هغوی ته ورکوله د خوراک دپاره د خپلو قربانیو وازګه او د څښاک دپاره مو شراب ورکول اوس پرېږدئ چې دوی راشي او کومک درسره وکړي او راشي چې ساتنه ستاسو وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_38.mp3', '', 1761754199, 1761754199),
(42669, 'Deuteronomy 32:39', 'Deuteronomy', 32, 39, 'ایا په دې نه پوهېږئ؟ یوازېنی خدای یمه زه چې بل خدای نشته مرګ او ژوند دی زما په لاس کې ټپي کول او روغول دي زما په لاس کې او نه شي کولای هېڅوک مخالفت زما د کار سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_39.mp3', '', 1761754199, 1761754199),
(42670, 'Deuteronomy 32:40', 'Deuteronomy', 32, 40, 'لکه څنګه چې زه یمه تل ژوندی خدای زه خپل لاس پورته کوم او دا وعده کومه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_40.mp3', '', 1761754199, 1761754199),
(42671, 'Deuteronomy 32:41', 'Deuteronomy', 32, 41, 'زه به تېره کړمه خپله ځلانده توره او زه به وکړم انصاف زه به د خپلو دښمنانو څخه واخلم بدل او هغو خلکو ته به ورکړمه سزا څوک چې کرکه کړي له ما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_41.mp3', '', 1761754199, 1761754199),
(42672, 'Deuteronomy 32:42', 'Deuteronomy', 32, 42, 'وبه څڅیږي د دوی وینه زما د غشو څخه او وبه وژني زما توره هغه خلک چې مخالفت کړي زما زه به ټول اسیران مړه کړم او زه به پرې کړمه سرونه د دښمنانو د مشرانو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_42.mp3', '', 1761754199, 1761754199),
(42673, 'Deuteronomy 32:43', 'Deuteronomy', 32, 43, 'ای اسمانونو! خوشحالي وکړئ د څښتن د قوم سره ټولو خدایانو! وکړئ سجده د څښتن په مخکې هغه د خپلو دښمنانو څخه اخلي بدل چا چې وژلی دی قوم د هغه هغه پاکوي د خپل قوم ځمکه د هغې ناپاکۍ څخه چې پیدا شوې په سبب د ګناهونو د دوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_43.mp3', '', 1761754199, 1761754199),
(42674, 'Deuteronomy 32:46', 'Deuteronomy', 32, 46, 'هغه وویل: «تاسو به خامخا د دغو ټولو امرونو اطاعت کوئ چې نن ما درکړي دي. دا خپلو اولادونو ته تکراروئ، ترڅو هغوی په وفادارۍ سره د خدای ټولو قوانینو ته غاړه کېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_46.mp3', '', 1761754199, 1761754199),
(42675, 'Deuteronomy 32:47', 'Deuteronomy', 32, 47, 'دا تعلیم تشې خبرې نه دي بلکې ستاسو ژوند دی. د هغه په وسیله کولای شئ چې په هغه خاوره کې ډېره موده ژوند وکړئ چې د اردن د سیند په بلې غاړې باندې پرته ده او تاسو به یې زر ونیسئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_47.mp3', '', 1761754199, 1761754199),
(42676, 'Deuteronomy 32:48', 'Deuteronomy', 32, 48, 'په هماغه ورځ څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_48.mp3', '', 1761754199, 1761754199),
(42677, 'Deuteronomy 32:49', 'Deuteronomy', 32, 49, '«د عباریم غرونو ته چې د اریحا ښار ته مخامخ د موآب په خاوره کې دي، لاړ شه. د نبو غره ته وروخېژه او د کنعان خاورې ته وګوره چې زه به یې زر د اسراییلو قوم ته ورکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_49.mp3', '', 1761754199, 1761754199),
(42678, 'Deuteronomy 32:50', 'Deuteronomy', 32, 50, 'ته به په هغه غره باندې مړ شې لکه څنګه چې ستا ورور هارون د هور په غره باندې مړ شو او د خپلو نیکونو سره یوځای شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_50.mp3', '', 1761754199, 1761754199),
(42679, 'Deuteronomy 32:51', 'Deuteronomy', 32, 51, 'ځکه چې تاسو دواړو زما سره د اسراییلو د قوم په حضور کې د مریبه د چینې سره د صین په دښته کې چې د قادش ښار ته نژدې ده بې وفایي وکړه. زه خدای یم، خو تاسو هلته د اسراییلیانو په مخکې زما سره داسې د عزت او درناوي له مخې چلند ونه کړ چې زه یې لایق یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_51.mp3', '', 1761754199, 1761754199),
(42680, 'Deuteronomy 32:52', 'Deuteronomy', 32, 52, 'ته به هغه خاوره چې زه یې د اسراییلو قوم ته ورکوم د یو لېرې ځای څخه ووینې، خو هغې ته به ورداخل نه شې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy32_verse_52.mp3', '', 1761754199, 1761754199),
(42681, 'Jeremiah 10:1', 'Jeremiah', 10, 1, 'اے بنى اِسرائيلو، د مالِک خُدائ پېغام ته غوږ ونيسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_1.mp3', '', 1761754199, 1761754199),
(42682, 'Jeremiah 10:2', 'Jeremiah', 10, 2, 'مالِک خُدائ فرمائى چې، ”د نورو قومونو په طريقو تلل مۀ کوئ، او د هغوئ په شان په آسمان کښې د ستورو د ګردش او نښو نښانو نه مۀ يرېږئ تر دې چې هغوئ په خپله يريږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_2.mp3', '', 1761754199, 1761754199),
(42683, 'Jeremiah 10:3', 'Jeremiah', 10, 3, 'ځکه چې د نورو قومونو رِواج فضول دے، هغوئ د ځنګل نه ونه راووهى، او بيا کاريګر ترې نه په خپله په ترښځ بُت جوړوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_3.mp3', '', 1761754199, 1761754199),
(42684, 'Jeremiah 10:4', 'Jeremiah', 10, 4, 'او وروستو هغه په سرو او سپينو زرو باندې ښائسته کړى او بيا دوئ په څټک او مېخ سره دا بُت په يو ځائ کښې ټک وهى چې راونۀ غورزيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_4.mp3', '', 1761754199, 1761754199),
(42685, 'Jeremiah 10:5', 'Jeremiah', 10, 5, 'د هغوئ بُتان داسې دى لکه د بادرنګو په پټى کښې چې ګوډاګے د مارغانو د شړلو دپاره ودرولے شوے وى، کوم چې نۀ خبرې کولے شى، او نۀ هغه په خپله ګرځېدے شى، په کار دے چې نور خلق دا اوچت کړى. د هغوئ نه مۀ يرېږه، دوئ تا ته ضرر نۀ شى در رسولے او نۀ څۀ فائده درکولے شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_5.mp3', '', 1761754199, 1761754199),
(42686, 'Jeremiah 10:6', 'Jeremiah', 10, 6, 'اے مالِکه خُدايه، ستا په شان بل هيڅ څوک هم نشته، تۀ لوئ يې، او تۀ زورَور يې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_6.mp3', '', 1761754199, 1761754199),
(42687, 'Jeremiah 10:7', 'Jeremiah', 10, 7, 'اے د قومونو بادشاه، څوک به ستا نه نۀ يريږى؟ تۀ د ثناء او صِفت لائق يې. د دُنيا په ټولو هوښيارو خلقو او بادشاهتونو کښې بل څوک ستا په شان نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_7.mp3', '', 1761754199, 1761754199),
(42688, 'Jeremiah 10:8', 'Jeremiah', 10, 8, 'هغوئ ټول کم عقل او بې‌وقوفه دى، ځکه هغوئ چې د څۀ عبادت کوى هغه د لرګى نه جوړ شوى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_8.mp3', '', 1761754199, 1761754199),
(42689, 'Jeremiah 10:9', 'Jeremiah', 10, 9, 'هغوئ د ترسيس نه د سپينو زرو تختې او د اوفاز نه سرۀ زر راوړى. کله چې زرګر ترې نه بُت جوړ کړى نو بيا درزيان ورته آسمانى او کاسنى کپړې تياروى او هغۀ ته يې وراغوندى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_9.mp3', '', 1761754199, 1761754199),
(42690, 'Jeremiah 10:10', 'Jeremiah', 10, 10, 'بلکې مالِک خُدائ رښتونے خُدائ پاک دے. هغه ژوندے خُدائ پاک او ابدى بادشاه دے. د هغۀ د قهر و غضب نه ټوله دُنيا لړزيږى، قومونه د هغۀ غضب ته ټينګېدے نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_10.mp3', '', 1761754199, 1761754199),
(42691, 'Jeremiah 10:11', 'Jeremiah', 10, 11, 'هغه خلقو ته څوک چې د نورو معبودانو عبادت کوى دا ووايه چې، ”هغه تش په نامه معبودانو چې زمکه او آسمانونه يې نۀ دى جوړ کړى، هغه به د زمکې د مخ نه او د آسمان د لاندې نه بلکل ختم شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_11.mp3', '', 1761754199, 1761754199),
(42692, 'Jeremiah 10:12', 'Jeremiah', 10, 12, 'خو مالِک خُدائ په خپل قدرت سره زمکه جوړه کړه. او په خپل حکمت سره يې دُنيا قائمه کړه. او په خپل عقل يې آسمانونه خوارۀ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_12.mp3', '', 1761754199, 1761754199),
(42693, 'Jeremiah 10:13', 'Jeremiah', 10, 13, 'کله چې هغه برېښنا ته حُکم وکړى نو په آسمان کښې وريځې په غرار شى، هغه وريځې د زمکې د يو سر نه تر بل سره پورې خوروى. هغه برېښنا د باران سره رالېږى او د خپلو ذخيرو نه هوا رالوځوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_13.mp3', '', 1761754199, 1761754199),
(42694, 'Jeremiah 10:14', 'Jeremiah', 10, 14, 'د انسان ټول نسلونه بې‌عقله او بې‌علمه دى، هغه کاريګر چې بُتان جوړوى دوئ به د دې بُتانو په وجه وشرميږى، ځکه چې د دوئ بُتان هم دوکه ده او ساه په کښې نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_14.mp3', '', 1761754199, 1761754199),
(42695, 'Jeremiah 10:15', 'Jeremiah', 10, 15, 'دا بُتان فضول او سپک څيز دے. د حساب کِتاب په ورځ به دا ټول تباه شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_15.mp3', '', 1761754199, 1761754199),
(42696, 'Jeremiah 10:16', 'Jeremiah', 10, 16, 'خو د بنى اِسرائيلو خُدائ د بُت په شان نۀ دے. هغه د هر شى خالق دے، د بنى اِسرائيلو په شمول چې د هغۀ خپل خلق دى. او د هغۀ نوم مالِک خُدائ ربُ الافواج دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_16.mp3', '', 1761754199, 1761754199),
(42697, 'Jeremiah 10:17', 'Jeremiah', 10, 17, 'اے محاصره شوې ښاريې. تاسو خپله کډه راوچته کړئ، دشمنانو درنه ګېره اچولې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_17.mp3', '', 1761754199, 1761754199),
(42698, 'Jeremiah 10:18', 'Jeremiah', 10, 18, 'ځکه مالِک خُدائ داسې فرمائى چې، ”ناګهانه به دا ځل د دې مُلک اوسېدونکى بهر وغورزوم. زۀ به په تاسو لوئ مصيبت نازل کړم، او په آخر کښې به تاسو ته زما د غصې پته ولګى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_18.mp3', '', 1761754199, 1761754199),
(42699, 'Jeremiah 10:19', 'Jeremiah', 10, 19, 'واى واى، تباه شوم، زما زخمونه سخت دى، زما بيمارى د رغېدو نه بهر ده، چې ضرور دا برداشت کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_19.mp3', '', 1761754199, 1761754199),
(42700, 'Jeremiah 10:20', 'Jeremiah', 10, 20, 'بلکې زمونږ خېمې تباه شوې دى او پړى يې شلېدلى دى، زما ماشومان ما نه اخستے شوى دى. يو هم نۀ دے پاتې شوے، ټول بوتلے شوى دى زۀ به يې دوباره ونۀ وينم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_20.mp3', '', 1761754199, 1761754199),
(42701, 'Jeremiah 10:21', 'Jeremiah', 10, 21, 'زما د قوم شپونکى بې‌شعوره او بې‌عقله شوى دى. دوئ نور د مالِک خُدائ سره مشوره نۀ کوى. نو په دې وجه دوئ پوره ناکاميابه شوى دى، او د دوئ ټولې رمې دانه وانه شوې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_21.mp3', '', 1761754199, 1761754199),
(42702, 'Jeremiah 10:22', 'Jeremiah', 10, 22, 'غوږ ونيسئ، د شمال د خوا نه د غټ لښکر د راتلو يروونکے شور اورېدے کيږى. د يهوداه ښارونه به تباه او برباد شى او د ګيدړانو غار به ترې نه جوړ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_22.mp3', '', 1761754199, 1761754199),
(42703, 'Jeremiah 10:23', 'Jeremiah', 10, 23, 'اے مالِکه خُدايه، زۀ په دې پوهېږم چې د انسان د ژوندون اختيار د دۀ په خپل لاس کښې نۀ دے. او نۀ هغه په خپلې مرضۍ سره د خپل ژوند لار مقررولے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_23.mp3', '', 1761754199, 1761754199),
(42704, 'Jeremiah 10:24', 'Jeremiah', 10, 24, 'اے مالِکه خُدايه، په نرمۍ سره زما اصلاح وکړه، او په خپل قهر او غضب کښې دې زما اصلاح مۀ کوه ګنې زۀ به د دُنيا نه ورک شم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_24.mp3', '', 1761754199, 1761754199),
(42705, 'Jeremiah 10:25', 'Jeremiah', 10, 25, 'څوک چې تا نۀ پېژنى خپل قهر و غضب دې په هغه خلقو نازل کړه، او په هغه چا څوک چې ستا نوم په خولۀ نۀ اخلى، ځکه چې ستا قوم بنى اِسرائيل يې وژلى دى، او هغوئ دوئ لواړ تېر کړى او تباه کړى يې دى، او مُلک يې ورله وران ويجاړ کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah10_verse_25.mp3', '', 1761754199, 1761754199),
(42706, 'Jeremiah 27:1', 'Jeremiah', 27, 1, 'د صدقياه د يوسياه د زوئ د يهوداه د بادشاهۍ په تازه ورځو کښې دا پېغام يرمياه ته د مالِک خُدائ له طرفه ورکړے شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_1.mp3', '', 1761754199, 1761754199),
(42707, 'Jeremiah 27:2', 'Jeremiah', 27, 2, 'مالِک خُدائ ما ته وفرمائيل چې، ”د خپل ځان دپاره جغ جوړ کړه او د څرمنې په تسمو سره يې په خپله غاړه کښې واچوه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_2.mp3', '', 1761754199, 1761754199),
(42708, 'Jeremiah 27:3', 'Jeremiah', 27, 3, 'بيا مالِک خُدائ ما ته وفرمائيل چې، ”د ادوم، موآب، عمون، صور او د صيدا بادشاهانو ته د هغوئ د هغه سفيرانو په ذريعه پېغام ورواستوه څوک چې يروشلم ته د يهوداه د بادشاه صدقياه ليدلو له راغلى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_3.mp3', '', 1761754199, 1761754199),
(42709, 'Jeremiah 27:4', 'Jeremiah', 27, 4, 'هغوئ له دا پېغام د هغوئ د مالِکانو دپاره ورکړه چې دا هغه څۀ دى چې ربُ الافواج د بنى اِسرائيلو مالِک خُدائ يې فرمائى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_4.mp3', '', 1761754199, 1761754199),
(42710, 'Jeremiah 27:5', 'Jeremiah', 27, 5, 'ما په خپل لوئ طاقت او زورَور لاس سره زمکه او په کښې ټول انسانان او ځناور پېدا کړل، او هر چا ته چې زما خوښه وى نو بيا دا هغوئ له ورکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_5.mp3', '', 1761754199, 1761754199);